from collections import deque

def bfs_path(graph, start, goal):
    parent = [-1] * len(graph)
    parent[start] = start
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node == goal:
            break
        for neighbor in graph[node]:
            if parent[neighbor] == -1:
                parent[neighbor] = node
                queue.append(neighbor)
    if parent[goal] == -1:
        return []
    path = [goal]
    while path[-1] != start:
        path.append(parent[path[-1]])
    return path[::-1]

