// matrix is a flat V-by-V adjacency matrix; nonzero means edge.
// Caller provides out[V]. Return the path length (0 if unreachable).
int bfs_path(const int *matrix, int V, int start, int goal, int *out) {
    int parent[V], queue[V], head = 0, tail = 0;
    for (int i = 0; i < V; i++) parent[i] = -1;
    parent[start] = start;
    queue[tail++] = start;
    while (head < tail) {
        int node = queue[head++];
        if (node == goal) break;
        for (int next = 0; next < V; next++) {
            if (matrix[node * V + next] && parent[next] == -1) {
                parent[next] = node;
                queue[tail++] = next;
            }
        }
    }
    if (parent[goal] == -1) return 0;
    int len = 0, node = goal;
    for (;;) {
        out[len++] = node;
        if (node == start) break;
        node = parent[node];
    }
    for (int i = 0; i < len / 2; i++) {
        int tmp = out[i]; out[i] = out[len-1-i]; out[len-1-i] = tmp;
    }
    return len;
}

