// pairs is flat [course, prerequisite, ...], E pairs.
// Caller provides out[V]. Return V on success, 0 for a cycle, -1 on allocation failure.
int course_order(int V, const int *pairs, int E, int *out) {
    int *head = malloc((size_t)V * sizeof(int));
    int *degree = calloc((size_t)V, sizeof(int));
    int *queue = malloc((size_t)V * sizeof(int));
    int *to = malloc((size_t)(E ? E : 1) * sizeof(int));
    int *next = malloc((size_t)(E ? E : 1) * sizeof(int));
    if (!head || !degree || !queue || !to || !next) {
        free(head); free(degree); free(queue); free(to); free(next); return -1;
    }
    for (int i = 0; i < V; i++) head[i] = -1;
    for (int e = 0; e < E; e++) {
        int course = pairs[2*e], pre = pairs[2*e+1];
        to[e] = course; next[e] = head[pre]; head[pre] = e;
        degree[course]++;
    }
    int front = 0, back = 0, count = 0;
    for (int i = 0; i < V; i++) if (!degree[i]) queue[back++] = i;
    while (front < back) {
        int node = queue[front++]; out[count++] = node;
        for (int e = head[node]; e != -1; e = next[e]) {
            int neighbor = to[e];
            if (--degree[neighbor] == 0) queue[back++] = neighbor;
        }
    }
    free(head); free(degree); free(queue); free(to); free(next);
    return count == V ? V : 0;
}

