// Returns -1 on allocation failure. Saturation prevents intermediate overflow;
// it does not change the answer under the signed-32-bit-result constraint.
int coin_change(int amount, const int *coins, int n) {
    unsigned long long *dp = calloc((size_t)amount + 1, sizeof(*dp));
    if (!dp) return -1;
    dp[0] = 1;
    const unsigned long long cap = 2147483648ULL;
    for (int i = 0; i < n; i++) {
        for (int s = coins[i]; s <= amount; s++) {
            unsigned long long sum = dp[s] + dp[s - coins[i]];
            dp[s] = sum < cap ? sum : cap;
        }
    }
    int result = (int)dp[amount];
    free(dp);
    return result;
}

