int can_partition(const int *nums, int n) {
    int total = 0;
    for (int i = 0; i < n; i++) total += nums[i];
    if (total % 2) return 0;
    int target = total / 2;
    unsigned char *dp = calloc((size_t)target + 1, sizeof(*dp));
    if (!dp) return -1;
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        for (int s = target; s >= nums[i]; s--)
            dp[s] = dp[s] || dp[s - nums[i]];
    }
    int result = dp[target];
    free(dp);
    return result;
}

